'use strict';
window.Shop = (() => {
 const KEY='ttakmatne-save-v1', VERSION=1, M=ShopData.missions;
 const people=[['토리','든든한 목수'],['느릿','느긋한 찻집 주인'],['루루','꽃을 돌보는 정원사'],['뽀득','호기심 많은 발명가'],['밤이','꼼꼼한 문양 연구가'],['콩이','활기찬 수레 상인'],['여울','숲속의 배달부'],['다솜','축제 준비 위원'],['몽글','함께 배우는 구름 조수'],['남자 수리사','나의 모습'],['여자 수리사','나의 모습'],['할머니','모양숲 수리점의 첫 주인']];
 const chapters=[['개업 첫 주문','합동 · 포개어 확인하기',0,'오늘은 수리점의 새 사장님이 오는 날! 다리부터 함께 고쳐 볼까?'],['다리를 건너는 방법','합동 · 대응하는 곳 찾기',0,'치수가 번진 주문서도 대응하는 곳을 찾으면 고칠 수 있어.'],['꽃길을 접으면','선대칭 · 대칭축 알아보기',2,'어느 선으로 접으면 꽃길이 딱 맞게 겹칠까?'],['반쪽 정원 완성하기','선대칭 · 성질과 그리기',2,'꽃씨 하나에도 자리가 있어. 반대편 정원을 함께 완성하자.'],['반 바퀴의 비밀','점대칭 · 중심 알아보기',4,'탑의 문양은 반 바퀴를 돌려도 같은 모습이래.'],['반대편에 켜지는 빛','점대칭 · 성질과 그리기',4,'중심을 사이에 두고 조명을 놓으면 탑에 불이 켜질 거야.'],['함께 만드는 반짝 축제','합동과 대칭 · 함께 적용하기',7,'우리가 고친 물건이 모두 모였어. 마지막은 네 깃발이야!']];
 const closing=['몽글이 작은 작업 장갑을 끼었어요. “내일은 나도 주문서를 읽어 볼게!”','꽃수레가 완성된 다리를 건넜어요. 루루가 정원 지도를 펼칩니다. “접히는 선을 찾아 줄래?”','연과 장식이 정원 위에 걸렸어요. 몽글이 놓은 꽃씨 하나가 조금 이상한 것 같아요.','정원 문이 활짝 열렸어요. 밤이가 문양판을 들고 찾아왔어요. “탑의 비밀을 함께 풀어 보자.”','탑 중간의 조명이 켜졌어요. 밤이는 남은 반쪽 문양을 조심스럽게 펼칩니다.','탑의 준비등이 반짝! 다솜이 말해요. “내일은 우리 모두의 물건을 광장으로 가져올게.”','할머니가 돌아왔어요. “네 손으로 마을을 이렇게 바꿨구나. 이 깃발은 오래 기억될 거야.”'];
 const colors=['#eab857','#da8065','#709784','#789aad','#9673a4','#f7ecd4'];
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const emptyRun=()=>({completed:{},drafts:{},lastMission:'D1-01',score:100,wrong:0});
 const fresh=()=>({schema:VERSION,revision:0,updatedAt:0,profile:{name:'',avatar:0,avatarChosen:false,flower:colors[1],light:colors[0],wrap:colors[2]},settings:{sound:true,music:true,effects:true,musicVolume:25,reducedMotion:false},runs:{story:emptyRun(),classroom:emptyRun(),trial:emptyRun(),practice:emptyRun()},flag:{type:'line',cells:Array(64).fill(''),auto:false},rpg:{introGuided:false,position:{x:906,y:792,dir:0}}});
 let state=fresh(),saveStatus='ok',rawUnreadable='',seenRevision=0,saveNotice='',route='home',mode='story',chapter=1,current=null,draft=null,active=null,lastComplete=null,pendingRepair=null,checking=false,night=false,toastTimer=null,pendingHint=null,footerObserver=null;
 const $=s=>document.querySelector(s),count=(r=run())=>Object.keys(r.completed).filter(id=>M.some(m=>m.id===id)).length;
 function validate(x){if(!x||x.schema!==VERSION||!x.runs||!x.profile||!x.settings||!x.flag)throw Error('지원하는 수리 기록 파일이 아니에요.');let n=fresh();n.revision=Number.isSafeInteger(x.revision)?Math.max(0,x.revision):0;n.updatedAt=Number(x.updatedAt)||0;n.profile.name=String(x.profile.name||'').slice(0,12);n.profile.avatar=x.profile.avatar===1?1:0;n.profile.avatarChosen=x.profile.avatarChosen===true;for(const k of ['flower','light','wrap'])if(colors.includes(x.profile[k]))n.profile[k]=x.profile[k];n.settings.sound=typeof x.settings.sound==='boolean'?x.settings.sound:true;n.settings.music=x.settings.music!==false;n.settings.effects=x.settings.effects!==false;n.settings.musicVolume=typeof x.settings.musicVolume==='number'&&Number.isFinite(x.settings.musicVolume)?Math.max(0,Math.min(100,Math.round(x.settings.musicVolume))):25;n.settings.reducedMotion=x.settings.reducedMotion===true;for(const key of ['story','classroom','trial','practice']){const r=x.runs[key];if(!r||typeof r!=='object')throw Error('기록의 일부가 빠져 있어요.');for(const m of M){let c=r.completed?.[m.id];if(c&&typeof c==='object')n.runs[key].completed[m.id]={hints:Math.min(3,Math.max(0,Number(c.hints)||0)),attempts:Math.min(999,Math.max(0,Number(c.attempts)||0)),completedAt:Number(c.completedAt)||0,independent:c.independent===true};const d=r.drafts?.[m.id];if(d&&typeof d==='object'&&JSON.stringify(d).length<18000)n.runs[key].drafts[m.id]=JSON.parse(JSON.stringify(d));}n.runs[key].score=Number.isSafeInteger(r.score)?Math.max(-999990,Math.min(999990,r.score)):100+10*Object.keys(n.runs[key].completed).length;n.runs[key].wrong=Number.isSafeInteger(r.wrong)?Math.max(0,r.wrong):0;if(M.some(m=>m.id===r.lastMission))n.runs[key].lastMission=r.lastMission;}if(Array.isArray(x.flag.cells)&&x.flag.cells.length===64)n.flag.cells=x.flag.cells.map(c=>colors.includes(c)?c:'');n.flag.type=x.flag.type==='point'?'point':'line';n.flag.auto=x.flag.auto===true;n.rpg.introGuided=x.rpg?.introGuided===true||!!n.runs.story.completed['D1-01'];const pos=x.rpg?.position;if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.y))n.rpg.position={x:Math.max(0,Math.min(1536,pos.x)),y:Math.max(0,Math.min(1024,pos.y)),dir:[0,1,2,3,4,5,6,7].includes(pos.dir)?pos.dir:0};return n}
 try{const raw=localStorage.getItem(KEY);if(raw){rawUnreadable=raw;state=validate(JSON.parse(raw));rawUnreadable='';seenRevision=state.revision}}catch(e){saveStatus=rawUnreadable?'blocked':'unavailable';saveNotice=rawUnreadable?'기존 기록을 읽지 못했어요. 원본을 보존하고 있어요. 설정에서 기록을 내보낼 수 있어요.':'이 브라우저에서는 저장이 제한돼요. 설정에서 수리 기록을 파일로 보관해 주세요.'}
 function run(){return state.runs[mode]}
 function commit(force=false){if(saveStatus==='blocked'||saveStatus==='conflict')return false;state.updatedAt=Date.now();state.revision=Math.max(state.revision,seenRevision)+1;try{const latest=localStorage.getItem(KEY);if(latest&&!force){const revision=Number(JSON.parse(latest).revision)||0;if(revision>seenRevision){saveStatus='conflict';saveNotice='다른 창에서 기록이 바뀌었어요. 최신 기록을 불러와 주세요.';queueMicrotask(()=>modal('다른 창의 기록이 바뀌었어요','<p>현재 창이 오래된 기록으로 덮어쓰지 않도록 저장을 멈췄어요. 현재 기록을 보관한 뒤 최신 기록을 불러와 주세요.</p>','<button class="btn secondary" data-action="backup">현재 기록 보관</button><button class="btn gold" data-action="reload-state">최신 기록 불러오기</button>'));return false}}localStorage.setItem(KEY,JSON.stringify(state));seenRevision=state.revision;saveStatus='ok';return true}catch(e){saveStatus='unavailable';saveNotice='자동 저장을 하지 못했어요. 지금 진행은 유지돼요. 설정에서 기록을 파일로 보관해 주세요.';return false}}
 function saveDraft(){if(current&&draft){run().drafts[current.id]=JSON.parse(JSON.stringify(draft));run().lastMission=current.id;commit()}}
 function icon(name){const d={map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z"/><path d="M9 3v16M15 5v16"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1V10Z"/>',book:'<path d="M12 5c-3-2-7-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-6-1-9 1Zm0 0v15"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>',sound:'<path d="m4 9 4 0 5-4v14l-5-4H4Z M17 8c3 2 3 6 0 8"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',flag:'<path d="M5 22V3m0 1c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>',check:'<path d="m5 12 4 4L19 6"/>'}[name]||'<circle cx="12" cy="12" r="8"/>';return`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`}
 function avatar(id,size=''){return`<span class="avatar ${size}" data-person="${id}" role="img" aria-label="${people[id][0]}"></span>`}
 function person(m){const n=m.who;return n.startsWith('몽글')?8:n.startsWith('모든')?7:Math.max(0,people.findIndex(p=>n.startsWith(p[0])))}
 function scene(day,id=current?.id){const special={'D1-02':6,'D1-03':5,'D1-04':6,'D1-05':6,'D2-01':4,'D2-03':4,'D2-04':6,'D3-03':5,'D3-04':5,'D3-05':5,'D4-03':5};return special[id]??(day===7?7:day<3?1:day<5?2:3)}
 function modeMissions(){return mode==='practice'?M.filter(m=>['D2-05','D4-05','D6-05'].includes(m.id)):M}
 function modeName(){return{story:'이야기',classroom:'수업용',practice:'추가 주문'}[mode]}
 function header(){return`<header class="topbar"><button class="brand" data-action="home" aria-label="딱맞네 수리점 처음 화면"><span class="brand-mark">◫</span><span><strong>딱맞네 수리점</strong><small>모양숲 반짝 축제 대작전</small></span></button><div class="top-actions">${route!=='home'?`<span class="pill"><strong class="score-pill"><span id="top-score">${run().score}</span>점</strong><span class="star">✦</span> ${count()} <span class="muted">/ ${modeMissions().length}</span><span class="mode-label">${modeName()}</span></span>`:'<span class="pill">5-2 합동과 대칭</span>'}<button class="icon-btn sound-toggle" data-action="toggle-sound" aria-label="${state.settings.sound?'전체 소리 끄기':'전체 소리 켜기'}" aria-pressed="${state.settings.sound}" title="${state.settings.sound?'전체 소리 켜짐':'전체 소리 꺼짐'}">${icon('sound')}</button><button class="icon-btn" data-action="settings" aria-label="설정">${icon('settings')}</button></div></header>${saveStatus!=='ok'?`<div class="save-warning" role="status">${escape(saveNotice)}</div>`:''}`}
 function nav(){return`<nav class="bottom-nav" aria-label="게임 메뉴">${[['home','home','수리점'],['map','map','마을 걷기'],['records','book','수리 기록'],['settings','settings','설정']].map(([a,i,t])=>`<button data-action="${a}" class="${route===a?'active':''}" ${route===a?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
 function home(){const repairs=count(state.runs.story),started=state.profile.avatarChosen||repairs>0||state.rpg.introGuided;return`<main class="title-screen" id="main"><img class="title-landscape" src="assets/village.webp" alt="다리와 꽃 정원, 시계탑이 있는 모양숲 마을" fetchpriority="high"><div class="title-shade"></div><div class="title-top"><span>합동과 대칭 · 모양숲 모험</span><button class="title-settings" data-action="settings" aria-label="설정">설정</button></div><div class="title-logo"><p class="title-prologue">할머니의 작은 가게, 나의 첫 모험</p><h1><span>딱맞네</span><strong>수리점</strong></h1><p class="title-subtitle">모양숲의 반짝 축제</p></div><section class="title-menu" aria-label="게임 시작"><span class="title-friend friend-left" aria-hidden="true"></span><span class="title-friend friend-right" aria-hidden="true"></span><p class="title-invitation">${started?'이웃들이 수리사님을 기다리고 있어요.':'어서 와요, 수리사님!'}</p><button class="btn gold title-play" data-action="start">${started?'모험 이어하기':'모험 시작'}</button>${started?`<p class="title-save">${repairs}/35 수리 완료 · ${state.runs.story.score}점</p>`:'<p class="title-save">7일의 모험 · 35개의 수리 주문</p>'}<p class="device-orientation-guide" aria-label="권장 화면 방향"><span>태블릿·PC는 <strong>가로로</strong></span><span>휴대폰은 <strong>세로로</strong></span></p><div class="title-other"><button type="button" data-opening="open">오프닝 다시 보기</button><button data-action="classroom">수업 모드</button></div></section><footer class="title-footer"><p>100점으로 출발 · 주문 완료 +10점 · 오답 확인 −10점</p><div><span>2022 개정 교육과정 참고</span><span class="creator-credit">만든 이 · <span class="creator-signature"><img class="creator-dragon-logo" src="assets/changyong-profile-v2.jpg" width="25" height="25" alt="" aria-hidden="true" decoding="async">창용쌤</span></span></div></footer></main>`}
 function nextId(){return M.find(m=>!run().completed[m.id])?.id||'D7-05'}
 function unlocked(day){return mode!=='story'||day===1||M.filter(m=>Number(m.id[1])<day).every(m=>run().completed[m.id])}
 function isAvailable(id){if(mode==='practice')return modeMissions().some(m=>m.id===id);if(mode!=='story')return true;const i=M.findIndex(m=>m.id===id);return i>=0&&M.slice(0,i).every(m=>run().completed[m.id])}
 function selectChapter(day){if(!unlocked(day)){toast('앞선 주문을 마치면 새로운 지역이 열려요.');return}chapter=day;route='map';render()}
 function map(){if(mode==='story')return RepairWorld.render();if(mode==='practice')return smallMap();const ch=chapters[chapter-1],dc=M.filter(m=>+m.id[1]===chapter),done=dc.filter(m=>run().completed[m.id]).length;return`<main class="app-main" id="main"><div class="page-heading"><div><div class="eyebrow">MOYANG FOREST</div><h1>조금씩 살아나는 모양숲</h1><p>${mode==='story'?'고친 물건이 모이면, 우리 마을에 축제가 열려요.':modeName()+' 기록은 이야기와 따로 보관돼요.'}</p></div><button class="btn secondary small" data-action="toggle-night">${night?'낮 풍경':'저녁 풍경'}</button></div><div class="map-layout"><div class="map-art ${night?'night':''}">${worldMap()}${[[1,21,35,'개울 다리'],[3,51,22,'거울 정원'],[5,83,36,'반바퀴 공방'],[7,55,66,'축제 광장']].map(([d,x,y,t])=>{const complete=M.filter(m=>+m.id[1]>=d&&+m.id[1]<=Math.min(7,d+1)).every(m=>run().completed[m.id]);return`<button class="map-hotspot ${chapter>=d&&chapter<=Math.min(d+1,7)?'active':''} ${!unlocked(d)?'locked':''} ${complete?'complete':''}" style="left:${x}%;top:${y}%" data-action="chapter" data-day="${d}" aria-label="${t} ${unlocked(d)?'선택':'아직 잠김'}"><strong>${t}</strong><small>${complete?'복구 완료':unlocked(d)?d===7?'Day 7':'Day '+d+' · '+(d+1):'앞선 구역을 완성해요'}</small></button>`}).join('')}<div class="map-status">${giftPalette()}<strong>${count()===35?'우리들의 축제, 준비 완료!':'오늘의 작은 수리가 내일의 풍경이 돼요.'}</strong><p>수리 반짝 ${count()}개 · ${Math.floor(count()/5)}일의 이야기 완성</p></div></div><aside class="chapter-card"><div class="row" style="margin-top:0">${avatar(ch[2],'mini')}<span class="day">DAY ${chapter} / 7</span></div><h2>${ch[0]}</h2><p class="fine">${ch[1]}</p><p style="font-size:14px;margin-top:13px">${ch[3]}</p><div class="row"><span class="fine">오늘의 수리 ${done} / 5</span><div class="progress" style="flex:1"><span style="width:${done*20}%"></span></div></div><div class="tools">${[chapter%2?chapter:chapter-1,chapter%2?chapter+1:chapter].filter(d=>d<=7).map(d=>`<button data-action="chapter" data-day="${d}" class="${chapter===d?'selected':''}" ${!unlocked(d)?'disabled':''}>Day ${d}</button>`).join('')}</div><ol class="mission-list">${dc.map((m,i)=>`<li><button class="mission-item ${run().completed[m.id]?'completed':''} ${m.id===nextId()?'current':''}" data-action="mission" data-id="${m.id}" ${!isAvailable(m.id)?'disabled':''}><span class="number">${run().completed[m.id]?'✓':i+1}</span><span><strong>${m.title}</strong><small>${run().completed[m.id]?'다시 수리해 보기':isAvailable(m.id)?'주문 열기':'앞선 주문을 마쳐요'}</small></span></button></li>`).join('')}</ol></aside></div></main>${nav()}`}
 function smallMap(){return `<main class="app-main" id="main"><div class="page-heading"><div><div class="eyebrow">ONE MORE LITTLE CHALLENGE</div><h1>새 모양에 다시 도전</h1><p>배운 방법을 다른 도형에도 적용해 봐요. 이야기 기록과 따로 저장돼요.</p></div></div><div class="practice-grid">${modeMissions().map(m=>`<section class="paper-card"><div class="scene-preview" data-scene="${scene(+m.id[1],m.id)}"></div><span class="tag">${+m.id[1]<3?'합동':+m.id[1]<5?'선대칭':'점대칭'}</span><h2 style="font-size:22px;margin:13px 0">${m.title}</h2><p class="fine">${run().completed[m.id]?'다시 한번 다른 방법으로 생각해 봐요.':'차근차근 직접 조작해서 완성해요.'}</p><button class="btn gold" style="margin-top:20px" data-action="mission" data-id="${m.id}">${run().completed[m.id]?'다시 도전':'주문 열기'}</button></section>`).join('')}</div></main>${nav()}`}
 function worldMap(){const all=count()===35;let html=`<img class="world-image" src="assets/${all?(night?'festival':'village'):'unfinished'}.webp" alt="${all?'축제를 완성한 모양숲':'수리를 기다리는 모양숲'}">`;if(!all){for(const [day,clip]of[[2,'polygon(0% 12%,34% 12%,34% 40%,0% 40%)'],[4,'polygon(33% 0%,73% 0%,73% 39%,33% 39%)'],[6,'polygon(72% 0%,100% 0%,100% 52%,72% 52%)']]){if(Array.from({length:5},(_,i)=>`D${day}-${String(i+1).padStart(2,'0')}`).every(id=>run().completed[id]))html+=`<img class="world-image restored-region" src="assets/village.webp" style="clip-path:${clip}" alt="복구된 지역">`}}if(all)html+=`<canvas class="map-flag" width="160" height="160" aria-label="나의 축제 깃발"></canvas>`;return html}
 function order(){const d=+current.id[1],p=person(current),cfg=ShopActivities.config(current.id),quote=cfg.quote||current.goal;return`<main class="app-main" id="main"><div class="order-top"><div class="order-title"><div class="eyebrow">DAY ${d} · ${d<3?'합동':d<5?'선대칭':d<7?'점대칭':'종합'} · 주문 ${+current.id.slice(-2)} / 5</div><h1>${current.title}</h1></div><button class="btn secondary small" data-action="map">${mode==='story'?'마을로':'지도'}</button></div><div class="game-layout"><section class="task-card" aria-label="수리 작업대"><div class="task-ribbon">${avatar(p,'mini')}<p><strong>${people[p][0]}의 부탁</strong>${escape(cfg.instruction||quote)}</p></div><div id="activity" class="activity"></div><div class="activity-footer"><button id="order-scroll-hint" class="order-scroll-hint" data-action="more-tools" hidden>아래에 도구가 더 있어요 ↓</button><div id="order-feedback" class="feedback" role="status" aria-live="polite"></div><button class="hint-button" data-action="hint">${hintButtonContent()}</button><button class="btn gold" id="check-button" data-action="check">확인하기</button></div></section><aside class="game-sidebar"><div class="scene-preview" data-scene="${scene(d)}" role="img" aria-label="${current.scene}"></div><div class="resident-card">${avatar(p,'big')}<h3>${people[p][0]}</h3><span class="tag">${people[p][1]}</span><blockquote>“${escape(quote)}”</blockquote></div><p class="side-note">급하게 하지 않아도 괜찮아요.<br>틀린 부분은 고치고, 막히면 몽글과 함께 해 봐요.</p></aside></div></main>`}
 function startMission(id){checking=false;pendingHint=null;if(!isAvailable(id)){toast('앞선 주문부터 함께 고쳐 봐요.');return false}current=M.find(m=>m.id===id);if(!current)return false;chapter=+current.id[1];draft=run().drafts[id]?JSON.parse(JSON.stringify(run().drafts[id])):{hints:0,attempts:0,a:{}};if(draft.activityVersion!==2){draft.a={};draft.history=[];draft.activityVersion=2}if(!Array.isArray(draft.history))draft.history=[];draft.history=draft.history.filter(v=>v&&typeof v==='object'&&!Array.isArray(v)&&JSON.stringify(v).length<12000).slice(-15);if(!draft.a||typeof draft.a!=='object'||Array.isArray(draft.a))draft.a={};draft.hints=Math.min(3,Math.max(0,Math.floor(Number(draft.hints)||0)));draft.attempts=Math.min(999,Math.max(0,Math.floor(Number(draft.attempts)||0)));active=ShopActivities.create(current,draft.a);route='order';saveDraft();render();return true}
 function resolveAssets(html){return html.replace(/src="(assets\/[^"]+)"/g,(_,src)=>`src="${window.EMBEDDED_ASSETS?.[src]||src}"`)}
 function render(){window.RepairCinema?.close();footerObserver?.disconnect();footerObserver=null;active?.dispose?.();window.RepairWorld?.dispose();document.body.classList.toggle('reduce-motion',state.settings.reducedMotion);document.body.classList.toggle('is-title',route==='home');document.body.classList.toggle('is-order',route==='order');document.body.classList.toggle('is-world',route==='world'||(route==='map'&&mode==='story'));document.body.style.setProperty('--gift-wrap',state.profile.wrap);document.body.style.setProperty('--gift-flower',state.profile.flower);document.body.style.setProperty('--gift-light',state.profile.light);$('#app').innerHTML=resolveAssets(header()+({home,map,world:()=>RepairWorld.render(),journal,order,success,records,settings,ending,share}[route]||home)());if(route==='world'||(route==='map'&&mode==='story')){const repair=pendingRepair;pendingRepair=null;void RepairWorld.mount(repair)}if(route==='order'){renderActivity();const footer=document.querySelector('.activity-footer');const fitFooter=()=>{document.body.style.setProperty('--order-footer-height',footer.getBoundingClientRect().height+'px');updateOrderViewport()};fitFooter();footerObserver=new ResizeObserver(fitFooter);footerObserver.observe(footer);footerObserver.observe($('#activity'))}if(route==='ending'||route==='map')renderFlagThumb();if(route==='share')void drawShare();window.scrollTo(0,0);window.ShopOpening?.sync(route);window.ShopMusic?.sync()}
 function wideOrder(){return matchMedia('(min-width:740px) and (orientation:landscape)').matches}
 function arrangeActivity(){
  const root=$('#activity'),nodes=[...root.children].filter(el=>!el.matches('.question-navigation'));
  const layout=document.createElement('div'),visual=document.createElement('div'),stack=document.createElement('div'),tools=document.createElement('div');
  layout.className='activity-layout';visual.className='activity-visual';stack.className='board-stack';tools.className='activity-tools';
  visual.append(stack);layout.append(visual,tools);
  nodes.forEach((el,i)=>{el.style.setProperty('--activity-order',i);(el.matches('.workbench,.flag-row')?stack:tools).append(el)});
  const boards=[...stack.querySelectorAll('svg')];
  const total=boards.reduce((sum,el)=>sum+el.viewBox.baseVal.height/el.viewBox.baseVal.width,0);
  if(total)stack.style.setProperty('--board-ratio',1/total);
  root.append(layout);tools.addEventListener('toggle',updateOrderViewport,true);[visual,tools].forEach(el=>el.addEventListener('scroll',updateOrderViewport,{passive:true}));
 }
 function orderScrollers(){return [...document.querySelectorAll('.activity-visual,.activity-tools')].filter(el=>el.scrollHeight>el.clientHeight+8&&el.scrollTop+el.clientHeight<el.scrollHeight-8)}
 function updateOrderViewport(){if(route!=='order')return;const cue=$('#order-scroll-hint'),footer=document.querySelector('.activity-footer');if(!cue||!footer)return;if(wideOrder()){cue.hidden=!orderScrollers().length;cue.textContent='아래 내용 더 보기 ↓';return}cue.textContent='아래에 도구가 더 있어요 ↓';const cueHeight=cue.hidden?0:cue.getBoundingClientRect().height+6;const bottom=innerHeight-footer.getBoundingClientRect().height+cueHeight;cue.hidden=innerWidth>900||$('#activity').getBoundingClientRect().bottom<=bottom-8}

 function hintButtonContent(){const n=draft.hints||0;return `${avatar(8,'mini')}<span>몽글의 도움<small>${n} / 3 · ${n===3?'다시 보기 무료':'1회 −3점'}</small></span>`}
 function hintHistory(){return current.hints.slice(0,draft.hints||0).map((h,i)=>`<p><strong>힌트 ${i+1}</strong><br>${escape(h)}</p>`).join('')}
 function requestHint(){if(route!=='order'||!current||!draft)return;pendingHint=null;if(draft.hints>=3){modal('받은 힌트 다시 보기',`<div class="hint-history">${hintHistory()}</div><p class="fine">도움 3회를 모두 사용했어요. 다시 보는 데는 점수가 들지 않아요.</p>`,'<button class="btn gold" data-action="close-modal">문제로 돌아가기</button>');return}pendingHint=current.id;modal('몽글의 도움을 받을까요?',`<p>힌트는 주문마다 <strong>3번</strong> 받을 수 있어요.<br>한 번 사용할 때마다 <strong>3점이 줄어들어요.</strong></p><p class="hint-cost">${draft.hints+1}번째 도움 · ${run().score}점 → <strong>${run().score-3}점</strong></p>`,'<button class="btn secondary" data-action="close-modal">혼자 더 해볼게요</button><button class="btn gold" data-action="confirm-hint">도움 받기 · −3점</button>')}
 function useHint(){if(route!=='order'||pendingHint!==current?.id||!$('#modal').open||draft.hints>=3)return;pendingHint=null;draft.hints++;scoreChange(-3);draft.feedback='';draft.error=false;active.hint?.(draft.hints);saveDraft();renderActivity();modal('몽글의 힌트 '+draft.hints,`<p>${escape(current.hints[draft.hints-1])}</p><p class="hint-cost">−3점 반영 · 현재 ${run().score}점 · 남은 도움 ${3-draft.hints}회</p>`,'<button class="btn gold" data-action="close-modal">힌트 보고 계속하기</button>')}
 function renderActivity(focusKey){if(route!=='order')return;const layoutKey=current.id+':'+(draft.a.step??0)+':'+(draft.a.stage??'');const scrolls=$('#activity').dataset.layoutKey===layoutKey?[...document.querySelectorAll('.activity-visual,.activity-tools')].map(el=>el.scrollTop):[];$('#activity').dataset.layoutKey=layoutKey;active?.dispose?.();active=ShopActivities.create(current,draft.a);$('#activity').dataset.kind=ShopActivities.config(current.id).type;$('#activity').innerHTML=`<div class="question-navigation"><button class="btn secondary small" data-action="previous-step" ${draft.history?.length?'':'disabled'}>이전 단계 보기</button><span>완료 +10점 · 오답 −10점</span></div>`+active.render()+`${draft.hints?`<details class="hint-box"><summary>받은 힌트 ${draft.hints}개 다시 보기</summary><div class="hint-history">${hintHistory()}</div></details>`:''}`;arrangeActivity();active.bind?.();document.querySelectorAll('.activity-visual,.activity-tools').forEach((el,i)=>el.scrollTop=scrolls[i]||0);requestAnimationFrame(updateOrderViewport);const hintButton=document.querySelector('.hint-button');if(hintButton)hintButton.innerHTML=hintButtonContent();const message=$('#order-feedback');if(message){message.textContent=draft.feedback||'';message.classList.toggle('error',!!draft.error)}if(focusKey)document.querySelector(`[data-focus="${CSS.escape(focusKey)}"]`)?.focus({preventScroll:true})}
 function feedback(text,error=false){draft.feedback=text;draft.error=error;saveDraft();renderActivity()}
 function scoreChange(delta){run().score+=delta;const el=document.getElementById('top-score');if(el)el.textContent=run().score}
 function penalize(message){draft.attempts=(draft.attempts||0)+1;run().wrong++;scoreChange(-10);feedback('−10점 · '+message,true)}
 function check(){if(route!=='order'||!active||checking)return;checking=true;const checkButton=document.getElementById('check-button');if(checkButton)checkButton.disabled=true;setTimeout(()=>{checking=false;const b=document.getElementById('check-button');if(b)b.disabled=false},250);const before=JSON.parse(JSON.stringify(draft.a)),stepKey=JSON.stringify([before.step,before.stage]);let result=active.check();if(result.partial){if(stepKey!==JSON.stringify([draft.a.step,draft.a.stage])){draft.history.push(before);draft.history=draft.history.slice(-15)}feedback(result.message||'아직 놓지 않은 부분이 있어요.');return}if(result.ok){draft.attempts=(draft.attempts||0)+1;complete()}else penalize(result.message||current.feedback)}
 function complete(){const prev=run().completed[current.id];if(!prev)scoreChange(10);if(!prev)run().completed[current.id]={hints:draft.hints||0,attempts:draft.attempts||1,completedAt:Date.now(),independent:current.id!=='D7-05'&&!draft.hints};delete run().drafts[current.id];run().lastMission=nextId();if(current.id==='D7-05'&&active.exportFlag)state.flag=active.exportFlag();lastComplete=current;commit();tone();if(mode==='story'){pendingRepair=prev?null:current.id;route='world'}else route=current.id==='D7-05'?'ending':'success';render()}
 function success(){const m=lastComplete,d=+m.id[1],isEnd=m.id.endsWith('05');return`<main class="app-main" id="main"><div class="success-panel"><span class="success-badge">✦</span><div class="eyebrow" style="margin-top:23px">${isEnd?'A DAY WELL SPENT':'A LITTLE REPAIR, A BIG SMILE'}</div><h1>${isEnd?'오늘도 마을이 반짝!':'딱 맞아요, 수리 완료!'}</h1><p>${escape(m.reward)}</p><div class="scene-preview" data-scene="${scene(d)}"><div class="confetti"></div></div><div class="paper-card"><div class="row" style="margin:0 0 12px">${avatar(isEnd?8:person(m),'mini')}<strong>${isEnd?'몽글의 마감 일기':people[person(m)][0]+'의 한마디'}</strong></div><p>${escape(isEnd?closing[d-1]:'고마워! '+chapters[d-1][3])}</p>${isEnd?`<p style="margin-top:16px;font-size:14px">오늘의 선물 · ${d<3?'창가 장식':d<5?'꽃 장식':'별 조명'} 색을 골라요</p><div class="gift-options">${colors.slice(0,3).map(c=>`<button class="swatch ${state.profile[d<3?'wrap':d<5?'flower':'light']===c?'selected':''}" style="background:${c}" data-action="gift" data-color="${c}" aria-label="${colors.indexOf(c)+1}번 장식 색"></button>`).join('')}</div>`:''}</div><div class="row"><button class="btn gold" data-action="next">${mode==='practice'?'다른 새 주문':isEnd?'다음 이야기':'다음 주문'}</button><button class="btn secondary" data-action="map">마을 둘러보기</button></div><p class="fine" style="margin-top:20px">도움을 받아도 반짝은 똑같이 모여요. ${saveStatus==='ok'?'수리 기록이 저장됐어요.':'설정에서 기록을 파일로 보관해 주세요.'}</p></div></main>${nav()}`}
 function records(){return`<main class="app-main" id="main"><div class="page-heading"><div><div class="eyebrow">MY REPAIR JOURNAL</div><h1>차곡차곡, 수리 기록</h1><p>${modeName()}에서 쌓은 나의 경험이에요.</p></div><button class="btn secondary small" data-action="backup">기록 보관</button></div><div class="records-grid"><div class="stat"><span>수리한 주문</span><strong>${count()}<small style="font-size:14px"> / ${modeMissions().length}</small></strong></div><div class="stat"><span>혼자 방법을 찾았어요</span><strong>${Object.entries(run().completed).filter(([id,c])=>id!=='D7-05'&&c.independent).length}</strong></div><div class="stat"><span>도움과 함께 마쳤어요</span><strong>${Object.entries(run().completed).filter(([id,c])=>id!=='D7-05'&&!c.independent).length}</strong></div></div><p class="notice">힌트는 배우는 도구예요. 100점에서 시작해 주문을 처음 완료하면 +10점, 오답을 확인하면 −10점, 몽글의 도움을 한 번 받으면 −3점이에요. 도움은 주문마다 3회까지 받을 수 있고 받은 힌트 다시 보기는 무료예요. 미입력·도형 실험·이전 단계 보기는 점수가 변하지 않아요. 완료한 주문을 다시 풀어도 점수를 반복해서 얻지 않아요.</p><div class="paper-card">${modeMissions().map(m=>{const c=run().completed[m.id];return`<div class="record-row"><span class="muted">${m.id}</span><strong>${m.title}</strong><span class="tag ${c?'gold':''}">${c?m.id==='D7-05'?'창작 완료':c.independent?'혼자 해결':'도움받아 해결':run().drafts[m.id]?'진행 중':'아직 시작 전'}</span></div>`}).join('')}</div><div class="row" style="margin-top:22px"><button class="btn secondary" data-action="practice">새 도형에 도전</button><button class="btn secondary" data-action="classroom">단원별 연습</button></div></main>${nav()}`}
 function settings(){return`<main class="app-main" id="main"><div class="page-heading"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>나의 수리점 설정</h1></div></div><div class="settings-grid"><section class="paper-card"><h2>편하게 플레이하기</h2><fieldset class="avatar-picker"><legend>나의 모습</legend>${[0,1].map(i=>`<label><input type="radio" name="player-avatar" value="${i}" ${state.profile.avatar===i?'checked':''}>${avatar(9+i)}<span>${i?'여자':'남자'} 캐릭터</span></label>`).join('')}</fieldset><label class="field">깃발에 남길 별명 <input id="nickname" maxlength="12" value="${escape(state.profile.name)}" placeholder="입력하지 않아도 괜찮아요" autocomplete="off"></label><fieldset class="sound-settings"><legend>소리 설정</legend><label class="check-field">전체 소리 <input type="checkbox" id="sound" ${state.settings.sound?'checked':''}></label><label class="check-field">배경음악 <input type="checkbox" id="music" ${state.settings.music?'checked':''}></label><label class="check-field">미션 완료 효과음 <input type="checkbox" id="effects" ${state.settings.effects?'checked':''}></label><label class="music-volume-label" for="music-volume">배경음악 크기 <output id="music-volume-value" for="music-volume">${state.settings.musicVolume}%</output></label><input class="music-volume" id="music-volume" type="range" min="0" max="100" step="5" value="${state.settings.musicVolume}"><p class="fine" id="music-status" role="status" aria-live="polite"></p></fieldset><label class="check-field">움직임 줄이기 <input type="checkbox" id="motion" ${state.settings.reducedMotion?'checked':''}></label><p class="fine">문제를 풀 때는 음악이 조금 작아져요. 위쪽 스피커 버튼으로 모든 소리를 한 번에 켜거나 끌 수 있어요. 아래 저장 버튼을 누르면 설정이 적용돼요.</p><button class="btn small" data-action="save-settings" style="margin-top:20px">설정 저장</button></section><section class="paper-card"><h2>수리 기록 보관하기</h2><p style="font-size:14px;margin:15px 0">진행은 이 기기의 같은 브라우저에 저장돼요. 다른 기기나 브라우저로 옮길 때는 기록 파일을 사용해 주세요.</p><div class="row"><button class="btn secondary small" data-action="backup">기록 파일 저장</button><button class="btn secondary small" data-action="restore">기록 불러오기</button></div><input type="file" id="restore-file" class="restore-input" accept="application/json,.json"><p class="fine" style="margin-top:16px">별명과 학습 기록을 외부로 자동 전송하지 않아요. 인터넷판과 오프라인판의 진행은 따로 저장될 수 있어요.</p></section><section class="paper-card"><h2>선생님께</h2><p style="font-size:14px;margin:14px 0">수업용 시작에서 합동·선대칭·점대칭을 바로 고를 수 있어요. 이야기의 해금과 수업 기록은 분리됩니다.</p><button class="btn secondary small" data-action="classroom">수업용 시작</button><p class="fine" style="margin-top:16px">권장 흐름: 개념 확인 5분 → 해당 구역 주문 20~25분 → 짝에게 방법 설명 5분 → 새 도형 적용. 교사에게 자동 전송되는 기록은 없습니다.</p></section><section class="paper-card"><h2>처음부터 다시</h2><p style="font-size:14px;margin:14px 0">현재 ${modeName()} 모드의 기록만 지울 수 있어요. 먼저 기록 파일을 보관해 주세요.</p><button class="btn quiet small" data-action="reset-mode">${modeName()} 기록 초기화</button>${saveStatus==='blocked'?'<button class="btn quiet small" data-action="reset-all">읽지 못한 기록을 보관하고 새로 시작</button>':''}<p class="fine" style="margin-top:18px">딱맞네 수리점 RPG 2.8 · 합동과 대칭<br>그림과 배경음악은 이 게임을 위해 제작했습니다.</p></section></div></main>${nav()}`}
 const medals=[
  {key:'diamond',min:400,range:'400–450점',name:'다이아몬드',title:'모양숲의 전설',percent:5,color:'#a9e9ed',ink:'#215878'},
  {key:'platinum',min:350,range:'350–399점',name:'플래티넘',title:'빛나는 대칭 장인',percent:15,color:'#c8d7f3',ink:'#3d5289'},
  {key:'gold',min:250,range:'250–349점',name:'골드',title:'든든한 마을 수호자',percent:35,color:'#ffd477',ink:'#8c5b17'},
  {key:'silver',min:150,range:'150–249점',name:'실버',title:'멋진 모양 탐험가',percent:65,color:'#dce6e7',ink:'#546a73'},
  {key:'bronze',min:-Infinity,range:'149점 이하',name:'브론즈',title:'끝까지 해낸 수리사',percent:100,color:'#e9b58a',ink:'#8b5134'}
 ];
 function medalForScore(score){return medals.find(m=>score>=m.min)||medals[4]}
 function medalIcon(m){return `<svg class="medal-icon" viewBox="0 0 128 150" aria-hidden="true"><path d="M35 89 24 143 51 129 64 146 77 129 104 143 93 89" fill="${m.ink}"/><path d="m39 101-7 29 20-11 12 16 12-16 20 11-7-29" fill="${m.color}"/><circle cx="64" cy="59" r="51" fill="${m.color}" stroke="${m.ink}" stroke-width="4"/><circle cx="64" cy="59" r="41" fill="none" stroke="${m.ink}" stroke-width="1.5"/><path d="m64 27 29 23-29 38-29-38Z M35 50h58 M64 27 52 50l12 38 12-38Z" fill="#ffffff88" stroke="${m.ink}" stroke-width="2" stroke-linejoin="round"/></svg>`}
 function awardPanel(){if(mode!=='story'||count()!==35)return '<div class="award-pending"><strong>나만의 축제 깃발 완성!</strong><p>이야기 모드에서 35개 주문을 모두 마치면<br>최종 점수에 따라 완주 메달과 칭호를 받아요.</p></div>';const m=medalForScore(run().score);return `<section class="award-panel" data-medal="${m.key}" style="--medal-color:${m.color};--medal-ink:${m.ink}" aria-label="완주 메달"><div class="award-main">${medalIcon(m)}<div><span class="award-eyebrow">35개의 수리, 마침내 완주!</span><h2>${m.name} 메달</h2><p class="award-title">${escape(state.profile.name||'우리 수리사')}, <strong>${m.title}</strong></p><div class="award-score"><b>${run().score}<small>점</small></b><span>게임 등급 · 상위 ${m.percent}%</span></div></div></div><p class="award-disclaimer">‘상위 %’는 점수 구간에 붙인 게임 속 등급이에요.<br>실제 이용자 통계나 순위를 뜻하지 않아요.</p><details class="medal-guide"><summary>메달과 칭호 기준 보기</summary><div class="medal-tiers">${medals.map(t=>`<div class="medal-tier ${t.key===m.key?'earned':''}"><span>${t.name}<small>${t.title}</small></span><b>${t.range}<small>상위 ${t.percent}% 등급</small></b></div>`).join('')}</div><p>100점에서 시작 · 주문 완료 +10점 · 오답 확인 −10점<br>최고 450점 · 낮은 점수여도 완주 메달을 받아요.</p></details></section>`}
 function ending(){return`<main class="app-main ending" id="main"><div class="eyebrow">THE FESTIVAL IS OURS</div><h1>${escape(state.profile.name||'우리 수리사')}의 깃발이 올라갔어요!</h1><p>포개고, 접고, 돌렸던 작은 순간들이<br>모양숲의 반짝 축제가 되었어요.</p>${awardPanel()}${mode==='story'&&count()===35?'<button class="btn gold ending-film-button" data-action="restoration-replay" data-day="7">▶ 처음 마을에서 축제까지 · 다시 보기</button>':''}<div class="ending-scene"><img class="world-image" src="assets/festival.webp" alt="복구된 모양숲 축제"><canvas class="ending-flag" width="320" height="320" aria-label="내가 만든 대칭 깃발"></canvas><div class="confetti"></div><div class="ending-characters">${[9+state.profile.avatar,0,1,2,3,4,5,6,7,8,11].map(i=>avatar(i,'celebrating')).join('')}</div></div><div class="paper-card">${avatar(11)}${giftPalette()}<p>“네 손으로 마을을 이렇게 바꿨구나.<br>다음에는 어떤 모양을 만들어 볼까?”</p><p class="fine" style="margin-top:9px">수리점을 돌아온 할머니의 편지</p></div><div class="row"><button class="btn gold" data-action="share">내 축제 카드</button><button class="btn secondary" data-action="map">마을 구경</button><button class="btn secondary" data-action="practice">새 주문 도전</button></div></main>${nav()}`}
 function renderFlagThumb(){document.querySelectorAll('.ending-flag,.map-flag').forEach(c=>paintFlag(c,state.flag.cells))}
 function paintFlag(canvas,cells){const ctx=canvas.getContext('2d'),w=canvas.width/8;ctx.fillStyle='#fff2d5';ctx.fillRect(0,0,canvas.width,canvas.height);cells.forEach((c,i)=>{if(c){ctx.fillStyle=c;ctx.fillRect(i%8*w,Math.floor(i/8)*w,w,w)}})}
 function share(){return`<main class="app-main ending" id="main"><div class="eyebrow">A LITTLE MEMORY TO KEEP</div><h1>내 축제 카드</h1><p>깃발과 마을의 추억을 한 장에 담았어요.</p><canvas id="share-canvas" class="share-card" width="900" height="1600" aria-label="축제 결과 카드"></canvas><div class="row"><button class="btn gold" data-action="download-card" id="download-card" disabled>그림 저장</button><button class="btn secondary" data-action="native-share" id="native-share" disabled>공유하기</button><button class="btn secondary" data-action="copy-link">게임 링크 복사</button></div><p class="fine">카드에는 오답이나 힌트 기록을 담지 않아요.<br>저장이 어려우면 그림을 크게 열어 기기의 저장 기능을 사용할 수 있어요.</p><div class="row"><button class="btn quiet" data-action="view-card" id="view-card" disabled>그림 크게 보기</button></div></main>${nav()}`}
 let cardBlob=null,cardURL=null,cardGeneration=0;
 async function drawShare(){const generation=++cardGeneration;cardBlob=null;const cv=$('#share-canvas');if(!cv)return;const ctx=cv.getContext('2d');ctx.fillStyle='#f9efda';ctx.fillRect(0,0,900,1600);ctx.fillStyle='#234f44';ctx.fillRect(36,36,828,1528);ctx.fillStyle='#fff4dc';ctx.textAlign='center';ctx.font='bold 31px "Malgun Gothic",sans-serif';ctx.fillText('딱맞네 수리점',450,115);ctx.font='bold 57px "Malgun Gothic",sans-serif';ctx.fillText('모양숲 반짝 축제',450,211);try{const img=await loadImage('assets/festival.webp');ctx.save();ctx.beginPath();if(ctx.roundRect)ctx.roundRect(80,275,740,490,24);else ctx.rect(80,275,740,490);ctx.clip();ctx.drawImage(img,80,275,740,490);ctx.restore()}catch{ctx.fillStyle='#4c7053';ctx.fillRect(80,275,740,490)}const flag=document.createElement('canvas');flag.width=flag.height=320;paintFlag(flag,state.flag.cells);ctx.fillStyle=state.profile.wrap;ctx.fillRect(273,803,354,354);ctx.drawImage(flag,290,820,320,320);ctx.fillStyle='#fff4dc';ctx.font='bold 37px "Malgun Gothic",sans-serif';ctx.fillText((state.profile.name||'모양숲 수리사')+'의 깃발',450,1232);ctx.font='27px "Malgun Gothic",sans-serif';ctx.fillText('포개고, 접고, 돌려서 완성한 나의 축제',450,1304);ctx.fillStyle=state.profile.light;ctx.font='bold 29px "Malgun Gothic",sans-serif';const award=mode==='story'&&count()===35?medalForScore(run().score):null;ctx.fillText(award?award.name+' 메달 · '+run().score+'점':'합동과 대칭 · 창작 완료',450,1392);if(award){ctx.font='25px \"Malgun Gothic\",sans-serif';ctx.fillText(award.title,450,1434)}ctx.fillStyle='#cad6be';ctx.font='23px "Malgun Gothic",sans-serif';ctx.fillText(new Date().toLocaleDateString('ko-KR'),450,1480);cv.toBlob(b=>{if(generation!==cardGeneration||route!=='share')return;if(!b)return toast('그림을 저장하지 못했어요. 다시 열어 주세요.');cardBlob=b;if(cardURL)URL.revokeObjectURL(cardURL);cardURL=URL.createObjectURL(b);for(const id of ['download-card','native-share','view-card']){const el=$('#'+id);if(el)el.disabled=false}},'image/png')}
 function giftPalette(){return `<div class="gift-summary"><span>내가 고른 축제 색</span>${[['포장 끈','wrap'],['꽃 장식','flower'],['별 조명','light']].map(([t,k])=>`<span><i style="background:${state.profile[k]}"></i>${t}</span>`).join('')}</div>`}
 function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image;img.onload=()=>resolve(img);img.onerror=reject;img.src=window.EMBEDDED_ASSETS?.[src]||src})}
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 function backup(){download(new Blob([rawUnreadable||JSON.stringify(state,null,2)],{type:'application/json'}),'딱맞네수리점_수리기록.json');toast('수리 기록 파일을 준비했어요.')}
 function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
 function modal(title,body,buttons){const el=$('#modal');el.classList.remove('character-dialog');el.innerHTML=`<h2 id="modal-title">${title}</h2>${body}<div class="dialog-actions">${buttons}</div>`;if(!el.open)el.showModal();else el.querySelector('.dialog-actions button:not(:disabled)')?.focus()}
 function closeModal(){pendingHint=null;$('#modal').close();$('#modal').classList.remove('character-dialog')}
 function chooseCharacter(){modal('어떤 수리사가 되어 볼까요?',`<p class="character-intro">마음에 드는 모습으로 모양숲에 놀러 와요.</p><fieldset class="first-avatar-picker"><legend class="sr-only">캐릭터 선택</legend>${[0,1].map(i=>`<label class="first-avatar-card"><input type="radio" name="intro-avatar" value="${i}" ${state.profile.avatar===i?'checked':''}><span class="character-check" aria-hidden="true">✓</span>${avatar(9+i,'first-avatar')}<strong>${i?'여자':'남자'} 캐릭터</strong><span class="character-outfit">${i?'파란':'노란'} 앞치마 수리사</span></label>`).join('')}</fieldset><p class="character-note">나중에 설정에서 언제든 바꿀 수 있어요.</p>`,'<button class="btn gold begin-adventure" data-action="begin-adventure">이 모습으로 출발!</button><button class="btn quiet small" data-action="close-modal">돌아가기</button>');$('#modal').classList.add('character-dialog')}
 function classroom(practice=false){if(practice){window.ShopMusic?.activate();mode='practice';route='map';render();return}modal('어느 단원을 수리할까요?',`<p>${practice?'도형의 위치와 방향을 바꾼 주문에서 방법을 다시 확인해요.':'이야기 진행과 별도로 시작해요. 필요한 도구는 모두 준비되어 있어요.'}</p>`,[[1,'합동'],[3,'선대칭'],[5,'점대칭'],[7,'종합']].map(([d,t])=>`<button class="btn secondary" data-action="class-start" data-day="${d}" data-mode="${practice?'practice':'classroom'}">${t}</button>`).join('')+'<button class="btn quiet" data-action="close-modal">닫기</button>')}
 function next(){if(mode==='story'){go('world');return}if(mode==='practice'){route='map';render();return}const i=M.indexOf(lastComplete);if(i<34&&isAvailable(M[i+1].id))startMission(M[i+1].id);else{route='map';render()}}
 let audioCtx;function tone(){if(!state.settings.sound||!state.settings.effects)return;try{audioCtx ||= new(window.AudioContext||window.webkitAudioContext);Promise.resolve(audioCtx.resume()).then(()=>{if(!state.settings.sound||!state.settings.effects||document.hidden||audioCtx.state!=='running')return;const start=audioCtx.currentTime+.02;[523.25,659.25,783.99,1046.5].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(audioCtx.destination);const t=start+i*.10;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.27);o.onended=()=>{o.disconnect();g.disconnect()};o.start(t);o.stop(t+.28)})}).catch(()=>{})}catch{}}
 async function handle(action,b,e){if(action==='restoration-replay'){RepairCinema.open(Number(b.dataset.day));return}if(action.startsWith('world:')){RepairWorld.action(action.slice(6),b);return}if(action==='previous-step'){if(draft.history?.length){draft.a=draft.history.pop();draft.feedback='이전 단계예요. 확인 후 다음 단계로 다시 넘어갈 수 있어요.';draft.error=false;saveDraft();renderActivity()}return}if(action==='ending'){closeModal();go('ending');return}if(action==='journal'){go('journal');return}if(action.startsWith('act:')){active?.action(action.slice(4),b,e);return}if(action==='more-tools'){const options={top:Math.max(140,innerHeight*.4),behavior:state.settings.reducedMotion?'auto':'smooth'};if(wideOrder()){orderScrollers().forEach(el=>el.scrollBy(options))}else window.scrollBy(options);return}if(action==='check'){check();return}if(action==='hint'){requestHint();return}if(action==='confirm-hint'){useHint();return}if(action==='toggle-sound'){state.settings.sound=!state.settings.sound;commit();b.setAttribute('aria-pressed',String(state.settings.sound));b.setAttribute('aria-label',state.settings.sound?'전체 소리 끄기':'전체 소리 켜기');b.title=state.settings.sound?'전체 소리 켜짐':'전체 소리 꺼짐';const input=$('#sound');if(input)input.checked=state.settings.sound;if(state.settings.sound){window.ShopMusic?.activate();tone()}else window.ShopMusic?.sync();toast(state.settings.sound?'소리를 켰어요.':'모든 소리를 껐어요.');return}if(action==='close-modal'){closeModal();return}if(action==='start'){window.ShopMusic?.activate();closeModal();if(!state.profile.avatarChosen){chooseCharacter();return}mode='story';route='world';render();return}if(action==='begin-adventure'){window.ShopMusic?.activate();state.profile.avatar=Number($('input[name="intro-avatar"]:checked')?.value)===1?1:0;state.profile.avatarChosen=true;commit();closeModal();mode='story';route='world';render();return}if(action==='classroom'||action==='practice'){classroom(action==='practice');return}if(action==='class-start'){window.ShopMusic?.activate();mode=b.dataset.mode;chapter=+b.dataset.day;closeModal();route='map';render();return}if(action==='mission'){if(mode==='story'&&!run().completed[b.dataset.id]){go('world');RepairWorld.navigate(b.dataset.id)}else startMission(b.dataset.id);return}if(action==='chapter'){selectChapter(+b.dataset.day);return}if(action==='toggle-night'){night=!night;render();return}if(action==='next'){next();return}if(action==='gift'){state.profile[+lastComplete.id[1]<3?'wrap':+lastComplete.id[1]<5?'flower':'light']=b.dataset.color;commit();render();return}if(action==='backup'){backup();return}if(action==='restore'){$('#restore-file').click();return}if(action==='save-settings'){state.profile.avatar=Number($('input[name="player-avatar"]:checked')?.value)===1?1:0;state.profile.avatarChosen=true;state.profile.name=$('#nickname').value.trim().slice(0,12);state.settings.sound=$('#sound').checked;state.settings.music=$('#music').checked;state.settings.effects=$('#effects').checked;state.settings.musicVolume=Math.max(0,Math.min(100,Number($('#music-volume').value)||0));window.ShopMusic?.activate();state.settings.reducedMotion=$('#motion').checked;commit();render();toast('설정을 저장했어요.');return}if(action==='reset-mode'){modal('기록을 지울까요?',`<p>${modeName()}의 완료 기록과 진행 중인 주문을 지워요. 다른 모드의 기록은 남아요.</p>`,'<button class="btn secondary" data-action="close-modal">돌아가기</button><button class="btn" data-action="confirm-reset">기록 지우기</button>');return}if(action==='confirm-reset'){state.runs[mode]=emptyRun();if(mode==='story'){state.rpg={introGuided:false,position:{x:906,y:792,dir:0}};state.profile.avatarChosen=false}commit();closeModal();route=mode==='story'?'home':'map';chapter=1;render();return}if(action==='reset-all'){backup();modal('새 기록으로 시작할까요?','<p>먼저 원본 파일이 저장되었는지 확인해 주세요. 읽지 못한 기존 기록을 새 기록으로 바꿉니다.</p>','<button class="btn secondary" data-action="close-modal">돌아가기</button><button class="btn" data-action="confirm-reset-all">새 기록 시작</button>');return}if(action==='confirm-reset-all'){state=fresh();try{seenRevision=Number(JSON.parse(localStorage.getItem(KEY)||'{}').revision)||0}catch{seenRevision=0}saveStatus='ok';rawUnreadable='';commit(true);closeModal();route='home';render();return}if(action==='reload-state'){location.reload();return}if(action==='download-card'){if(cardBlob)download(cardBlob,'모양숲_나의축제.png');return}if(action==='view-card'){if(cardURL)window.open(cardURL,'_blank','noopener');return}if(action==='native-share'){if(!cardBlob)return;const file=new File([cardBlob],'모양숲_축제.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'딱맞네 수리점 · 나의 축제'});}else{download(cardBlob,'모양숲_나의축제.png');toast('기기 공유 대신 그림을 저장할 수 있어요.')}}catch(err){if(err.name!=='AbortError')toast('공유를 열지 못했어요. 그림 저장을 이용해 주세요.')}return}if(action==='copy-link'){if(location.protocol==='file:'||['127.0.0.1','localhost'].includes(location.hostname)){toast('배포된 게임 주소에서 링크를 복사할 수 있어요.');return}const url=location.origin+location.pathname;try{await navigator.clipboard.writeText(url);toast('게임 링크를 복사했어요.')}catch{modal('게임 링크',`<label class="field">주소를 길게 눌러 복사해 주세요.<input readonly value="${escape(url)}"></label>`,'<button class="btn" data-action="close-modal">닫기</button>')}return}if(['home','map','world','records','settings','share'].includes(action)){if(route==='order')saveDraft();route=action;if(action==='map'&&!unlocked(chapter))chapter=+nextId()[1];render()}}
 function go(next){if(route==='order')saveDraft();route=next;render()}
 function journal(){return `<main class="app-main" id="main"><div class="page-heading"><div><h1>우리 마을 수리 수첩</h1><p>완료 ${count()}/35 · ${run().score}점 · 오답 확인 ${run().wrong}회</p></div><button class="btn gold" data-action="world">마을로 돌아가기</button></div><div class="journal-days">${chapters.map((ch,i)=>`<section class="paper-card"><span class="tag">DAY ${i+1}</span><h2>${ch[0]}</h2><p class="fine">${RepairWorld.dayNames[i]}</p><ol class="mission-list">${M.filter(m=>Number(m.id[1])===i+1).map(m=>`<li><button class="mission-item ${run().completed[m.id]?'completed':''}" data-action="mission" data-id="${m.id}" ${!isAvailable(m.id)?'disabled':''}><span class="number">${run().completed[m.id]?'✓':Number(m.id.slice(-2))}</span><span><strong>${escape(m.title)}</strong><small>${run().completed[m.id]?'다시 살펴보기 · 추가 점수 없음':m.id===nextId()?'주민에게 걸어가기':'아직 수리 전'}</small></span></button></li>`).join('')}</ol>${mode==='story'&&M.filter(m=>Number(m.id[1])===i+1).every(m=>run().completed[m.id])?`<button class="btn secondary journal-film-button" data-action="restoration-replay" data-day="${i+1}">▶ 복구의 순간 다시 보기</button>`:''}</section>`).join('')}</div></main>${nav()}`}
 function init(){window.ShopMusic?.init(()=>({settings:state.settings,route}));window.ShopOpening?.init(()=>({settings:state.settings,route}));render();$('#app').addEventListener('input',e=>{if(e.target.id==='music-volume')$('#music-volume-value').textContent=e.target.value+'%'});window.addEventListener('scroll',updateOrderViewport,{passive:true});window.addEventListener('resize',updateOrderViewport);$('#app').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)void handle(b.dataset.action,b,e)});$('#modal').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)void handle(b.dataset.action,b,e)});$('#app').addEventListener('change',async e=>{if(e.target.id!=='restore-file')return;const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('기록 파일이 너무 커요.');const next=validate(JSON.parse(await f.text()));modal('보관한 기록을 불러올까요?','<p>현재 기록을 선택한 파일의 기록으로 바꿉니다. 먼저 현재 기록을 보관하면 안전하게 돌아올 수 있어요.</p>','<button class="btn secondary" data-action="backup">현재 기록 보관</button><button class="btn" id="confirm-restore">불러오기</button><button class="btn quiet" data-action="close-modal">취소</button>');$('#confirm-restore').onclick=()=>{state=next;try{seenRevision=Number(JSON.parse(localStorage.getItem(KEY)||'{}').revision)||0}catch{seenRevision=next.revision}rawUnreadable='';saveStatus='ok';commit(true);closeModal();route='home';render();toast('수리 기록을 불러왔어요.')}}catch(err){toast('불러오지 못했어요. '+(err.message.includes('JSON')?'기록 파일을 확인해 주세요.':err.message))}e.target.value=''});window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const incoming=validate(JSON.parse(e.newValue));if(incoming.revision===seenRevision)return;saveStatus='conflict';saveNotice='다른 창에서 수리 기록이 바뀌었어요. 최신 기록을 불러와 주세요.';modal('다른 창의 수리 기록이 바뀌었어요','<p>이 창이 오래된 기록으로 덮어쓰지 않도록 저장을 멈췄어요. 지금 기록을 파일로 보관하거나 최신 기록을 불러올 수 있어요.</p>','<button class="btn secondary" data-action="backup">현재 창 기록 보관</button><button class="btn gold" data-action="reload-state">최신 기록 불러오기</button>')}catch{}});registerTools()}
 function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController;try{Promise.resolve(ctx.registerTool({name:'read_repair_progress',description:'현재 모드의 완료 주문과 진행 상태를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return{mode,screen:route,completed:Object.keys(run().completed),current:route==='order'?current.id:null}}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(ctx.registerTool({name:'open_repair_order',description:'열려 있는 수리 주문을 작업대에서 시작합니다. 주문을 완료하거나 정답을 제출하지 않습니다.',inputSchema:{type:'object',properties:{missionId:{type:'string'}},required:['missionId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.missionId!=='string'||!M.some(m=>m.id===input.missionId)||!isAvailable(input.missionId))throw Error('열 수 없는 주문입니다.');startMission(input.missionId);return{opened:current.id,screen:route}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
 document.addEventListener('DOMContentLoaded',init);
 return{escape,avatar,colors,people,chapters,closing,medalForScore,personFor:person,startMission,go,showModal:modal,hideModal:closeModal,penalize,saveDraft,renderActivity,feedback,toast,paintFlag,commit,get state(){return state},get mode(){return mode},get current(){return current},get draft(){return draft},get active(){return active}};
})();
